-- Private, revisioned staff announcements. Apply after 20261119130000_staff_access.sql.
-- No recipient rows or notifications are generated by this migration.
begin;

create table public.announcements (
  id uuid primary key default gen_random_uuid(),
  author_id uuid not null references auth.users(id),
  status text not null default 'draft' check (status in ('draft','published','archived')),
  current_revision integer not null default 1 check (current_revision > 0),
  request_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index announcements_author_request on public.announcements(author_id,request_id) where request_id is not null;

create table public.announcement_revisions (
  announcement_id uuid not null references public.announcements(id),
  revision integer not null check (revision > 0),
  title text not null check (length(btrim(title)) between 1 and 160),
  body text not null check (length(btrim(body)) between 1 and 12000),
  audience_type text not null check (audience_type in ('company','departments')),
  departments text[] not null default '{}',
  expires_at timestamptz,
  published_at timestamptz,
  published_by uuid references auth.users(id),
  superseded_at timestamptz,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (announcement_id,revision),
  check ((audience_type='company' and cardinality(departments)=0) or
    (audience_type='departments' and cardinality(departments) between 1 and 5)),
  check (departments <@ array['graphics','development','communications','events','marketing']::text[]),
  check (published_at is null or published_by is not null)
);

create table public.announcement_acknowledgements (
  announcement_id uuid not null,
  revision integer not null,
  user_id uuid not null references auth.users(id),
  acknowledged_at timestamptz not null default now(),
  primary key (announcement_id,revision,user_id),
  foreign key (announcement_id,revision) references public.announcement_revisions(announcement_id,revision)
);

create table public.announcement_audit (
  id bigint generated always as identity primary key,
  announcement_id uuid not null references public.announcements(id),
  revision integer not null,
  actor_id uuid not null references auth.users(id),
  action text not null check (action in ('created','edited','revision_created','published','archived')),
  created_at timestamptz not null default now(),
  foreign key (announcement_id,revision) references public.announcement_revisions(announcement_id,revision)
);

create index announcement_revisions_published on public.announcement_revisions(published_at,announcement_id,revision)
  where published_at is not null;
create index announcement_audit_record on public.announcement_audit(announcement_id,id desc);
alter table public.announcements enable row level security;
alter table public.announcement_revisions enable row level security;
alter table public.announcement_acknowledgements enable row level security;
alter table public.announcement_audit enable row level security;
revoke all on public.announcements,public.announcement_revisions,public.announcement_acknowledgements,public.announcement_audit from public,anon,authenticated;
grant select on public.announcements,public.announcement_revisions,public.announcement_audit to authenticated;
grant select on public.announcement_acknowledgements to authenticated;

create function eba_private.announcement_active()
returns boolean language sql stable security definer set search_path=''
as $$ select exists(select 1 from public.staff_memberships m join auth.users u on u.id=m.user_id
 where m.user_id=auth.uid() and m.status='active' and m.role in ('ceo','admin')
 and lower(u.email) ~ '^[^@]+@enibrand[.]com$' and u.email_confirmed_at is not null and u.deleted_at is null
 and (u.banned_until is null or u.banned_until<=clock_timestamp())) $$;

create function eba_private.announcement_manage_access(record_id uuid)
returns boolean language sql stable security definer set search_path=''
as $$ select eba_private.announcement_active() and exists(select 1 from public.announcements a
 where a.id=record_id and (a.author_id=auth.uid() or a.status<>'draft')) $$;

create function eba_private.announcement_recipient_access(record_id uuid,rev integer)
returns boolean language sql stable security definer set search_path=''
as $$ select eba_private.announcement_active() and exists(
 select 1 from public.announcements a join public.announcement_revisions r
 on r.announcement_id=a.id and r.revision=a.current_revision
 where a.id=record_id and a.status='published' and r.revision=rev and r.published_at is not null
 and r.superseded_at is null and r.archived_at is null and (r.expires_at is null or r.expires_at>clock_timestamp())
 and (r.audience_type='company' or exists(
  select 1 from public.staff_department_assignments d
  where d.user_id=auth.uid() and d.department=any(r.departments)
 ))
 ) $$;

create policy "Announcement managers read permitted records" on public.announcements for select to authenticated
 using (eba_private.announcement_manage_access(id));
create policy "Announcement managers read permitted revisions" on public.announcement_revisions for select to authenticated
 using (eba_private.announcement_manage_access(announcement_id));
create policy "Users read own announcement acknowledgements" on public.announcement_acknowledgements for select to authenticated
 using (user_id=(select auth.uid()) and eba_private.announcement_active());
create policy "Announcement managers read permitted audit" on public.announcement_audit for select to authenticated
 using (eba_private.announcement_manage_access(announcement_id));

revoke all on function eba_private.announcement_active(),eba_private.announcement_manage_access(uuid),eba_private.announcement_recipient_access(uuid,integer) from public,anon,authenticated;
grant execute on function eba_private.announcement_active(),eba_private.announcement_manage_access(uuid),eba_private.announcement_recipient_access(uuid,integer) to authenticated,service_role;

create function public.announcement_manage(p_action text,p_id uuid default null,p_expected_revision integer default null,p_payload jsonb default '{}',p_request uuid default null)
returns jsonb language plpgsql security definer set search_path='' set lock_timeout='2s' as $$
declare person uuid:=auth.uid(); rec public.announcements; rev public.announcement_revisions; new_id uuid; n integer;
 title_value text; body_value text; audience text; departments_value text[]; expires_value timestamptz;
begin
 if not eba_private.announcement_active() then raise exception 'Active CEO or Admin required'; end if;
 if p_action not in ('create','create_publish','edit','publish','archive') then raise exception 'Invalid action'; end if;
 if p_action in ('create','create_publish') then
  title_value:=btrim(p_payload->>'title'); body_value:=btrim(p_payload->>'body'); audience:=p_payload->>'audience_type';
  select coalesce(array_agg(distinct value order by value),'{}') into departments_value from jsonb_array_elements_text(coalesce(p_payload->'departments','[]')) as d(value);
  expires_value:=nullif(p_payload->>'expires_at','')::timestamptz;
  if expires_value is not null and expires_value<=clock_timestamp() then raise exception 'Expiry must be in the future'; end if;
  if length(title_value) not between 1 and 160 or length(body_value) not between 1 and 12000 then raise exception 'Invalid title or message length'; end if;
  if audience not in ('company','departments') or audience is null or (audience='company' and cardinality(departments_value)>0)
   or (audience='departments' and cardinality(departments_value)=0) or cardinality(departments_value)>5
   or not departments_value <@ array['graphics','development','communications','events','marketing']::text[] then raise exception 'Invalid audience'; end if;
  if p_request is null then raise exception 'Request identifier required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(person::text||p_request::text,0));
  select id into new_id from public.announcements where author_id=person and request_id=p_request;
  if new_id is not null then
   select current_revision,status into n,audience from public.announcements where id=new_id;
   return jsonb_build_object('id',new_id,'revision',n,'status',audience);
  end if;
  insert into public.announcements(author_id,request_id) values(person,p_request) returning id into new_id;
  if p_action='create_publish' then
   update public.announcements set status='published' where id=new_id;
   insert into public.announcement_revisions(announcement_id,revision,title,body,audience_type,departments,expires_at,published_at,published_by)
    values(new_id,1,title_value,body_value,audience,departments_value,expires_value,clock_timestamp(),person);
   insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(new_id,1,person,'created'),(new_id,1,person,'published');
   return jsonb_build_object('id',new_id,'revision',1,'status','published');
  end if;
  insert into public.announcement_revisions(announcement_id,revision,title,body,audience_type,departments,expires_at)
   values(new_id,1,title_value,body_value,audience,departments_value,expires_value);
  insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(new_id,1,person,'created');
  return jsonb_build_object('id',new_id,'revision',1,'status','draft');
 end if;
 select * into rec from public.announcements where id=p_id for update;
 if not found or rec.author_id<>person then raise exception 'Announcement unavailable'; end if;
 if rec.current_revision is distinct from p_expected_revision then raise exception 'Announcement changed; reload it'; end if;
 select * into rev from public.announcement_revisions where announcement_id=rec.id and revision=rec.current_revision for update;
 if p_action='edit' then
  if rec.status='archived' then raise exception 'Archived announcements cannot be edited'; end if;
  title_value:=btrim(p_payload->>'title'); body_value:=btrim(p_payload->>'body'); audience:=p_payload->>'audience_type';
  select coalesce(array_agg(distinct value order by value),'{}') into departments_value from jsonb_array_elements_text(coalesce(p_payload->'departments','[]')) as d(value);
  expires_value:=nullif(p_payload->>'expires_at','')::timestamptz;
  if expires_value is not null and expires_value<=clock_timestamp() then raise exception 'Expiry must be in the future'; end if;
  if length(title_value) not between 1 and 160 or length(body_value) not between 1 and 12000 then raise exception 'Invalid title or message length'; end if;
  if audience not in ('company','departments') or audience is null or (audience='company' and cardinality(departments_value)>0)
   or (audience='departments' and cardinality(departments_value)=0) or cardinality(departments_value)>5
   or not departments_value <@ array['graphics','development','communications','events','marketing']::text[] then raise exception 'Invalid audience'; end if;
  if rec.status='published' then
   n:=rec.current_revision+1;
   update public.announcement_revisions set superseded_at=clock_timestamp() where announcement_id=rec.id and revision=rec.current_revision;
   insert into public.announcement_revisions(announcement_id,revision,title,body,audience_type,departments,expires_at)
    values(rec.id,n,title_value,body_value,audience,departments_value,expires_value);
   update public.announcements set current_revision=n,status='draft',updated_at=clock_timestamp() where id=rec.id;
   insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(rec.id,n,person,'revision_created');
  else
   update public.announcement_revisions set title=title_value,body=body_value,audience_type=audience,departments=departments_value,expires_at=expires_value
    where announcement_id=rec.id and revision=rec.current_revision;
   update public.announcements set updated_at=clock_timestamp() where id=rec.id;
   insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(rec.id,rec.current_revision,person,'edited');
  end if;
  return jsonb_build_object('id',rec.id,'revision',case when rec.status='published' then rec.current_revision+1 else rec.current_revision end,'status','draft');
 elsif p_action='publish' then
  if rec.status<>'draft' or rev.published_at is not null then raise exception 'Announcement is already published or unavailable'; end if;
  update public.announcement_revisions set published_at=clock_timestamp(),published_by=person where announcement_id=rec.id and revision=rec.current_revision and published_at is null;
  if not found then raise exception 'Announcement already published'; end if;
  update public.announcements set status='published',updated_at=clock_timestamp() where id=rec.id and status='draft';
  insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(rec.id,rec.current_revision,person,'published');
  return jsonb_build_object('id',rec.id,'revision',rec.current_revision,'status','published');
 else
  if rec.status<>'published' then raise exception 'Announcement unavailable'; end if;
  update public.announcements set status='archived',updated_at=clock_timestamp() where id=rec.id;
  update public.announcement_revisions set archived_at=clock_timestamp() where announcement_id=rec.id and revision=rec.current_revision;
  insert into public.announcement_audit(announcement_id,revision,actor_id,action) values(rec.id,rec.current_revision,person,'archived');
  return jsonb_build_object('id',rec.id,'revision',rec.current_revision,'status','archived');
 end if;
end $$;

create function public.announcement_next()
returns jsonb language plpgsql security definer set search_path='' as $$
declare person uuid:=auth.uid(); result jsonb;
begin
 if not eba_private.announcement_active() then raise exception 'Active CEO or Admin required'; end if;
 select jsonb_build_object('id',a.id,'revision',r.revision,'title',r.title,'body',r.body,'published_at',r.published_at)
 into result from public.announcements a join public.announcement_revisions r
 on r.announcement_id=a.id and r.revision=a.current_revision
 where eba_private.announcement_recipient_access(a.id,r.revision)
 and not exists(select 1 from public.announcement_acknowledgements k where k.announcement_id=a.id and k.revision=r.revision and k.user_id=person)
 order by r.published_at,a.id limit 1;
 return result;
end $$;

create function public.announcement_history()
returns table(id uuid,revision integer,title text,body text,audience_type text,departments text[],published_at timestamptz,expires_at timestamptz,acknowledged_at timestamptz)
language sql stable security definer set search_path='' as $$
 select a.id,r.revision,r.title,r.body,r.audience_type,r.departments,r.published_at,r.expires_at,k.acknowledged_at
 from public.announcements a join public.announcement_revisions r on r.announcement_id=a.id and r.revision=a.current_revision
 left join public.announcement_acknowledgements k on k.announcement_id=a.id and k.revision=r.revision and k.user_id=auth.uid()
 where eba_private.announcement_recipient_access(a.id,r.revision) order by r.published_at desc,a.id
 $$;

create function public.announcement_acknowledge(p_id uuid,p_revision integer)
returns boolean language plpgsql security definer set search_path='' as $$
declare person uuid:=auth.uid();
begin
 if not eba_private.announcement_recipient_access(p_id,p_revision) then raise exception 'Announcement unavailable'; end if;
 insert into public.announcement_acknowledgements(announcement_id,revision,user_id) values(p_id,p_revision,person)
 on conflict do nothing;
 return true;
end $$;

revoke all on function public.announcement_manage(text,uuid,integer,jsonb,uuid),public.announcement_next(),public.announcement_history(),public.announcement_acknowledge(uuid,integer) from public,anon;
grant execute on function public.announcement_manage(text,uuid,integer,jsonb,uuid),public.announcement_next(),public.announcement_history(),public.announcement_acknowledge(uuid,integer) to authenticated;
notify pgrst,'reload schema';
commit;
